-- =============================================================================
-- GHANI TRADERS STARTER CATALOG (fashion). Mirrors the demo-mode catalog so the
-- live store looks the same once Supabase is connected. Run once, after
-- supabase/bundle/setup.sql, in the SQL Editor. Replace products with the real
-- catalog from Admin → Products. Generated from src/features/catalog/demo-catalog.ts.
-- (supabase/seed.sql is the fixture the database tests use — leave it alone.)
-- =============================================================================

update public.store_settings set
  store_name = 'Ghani Traders',
  tagline = 'Considered clothing and leather goods for every day.',
  contact_phone = '+92 300 0000000',
  contact_address = 'Lahore, Pakistan',
  free_shipping_threshold = 10000,
  hero = jsonb_build_object(
    'title', 'Wear the moment. Carry it well.',
    'subtitle', 'Everyday clothing, leather bags and shoes, designed to be worn often and kept for years.',
    'cta_label', 'Shop collection',
    'cta_href', '/products',
    'image_url', '/demo/fashion/hero.webp'
  ),
  promo = jsonb_build_object(
    'eyebrow', 'New season',
    'title', 'The quilted bag is back.',
    'body', 'Diamond-quilted, gold-tone chain, made in small batches. Limited stock in black and cream.',
    'cta_label', 'Shop handbags',
    'cta_href', '/categories/handbags',
    'image_url', '/demo/fashion/promo.webp'
  ),
  policies = jsonb_build_object(
    'shipping', 'Orders are dispatched within 2 business days. Delivery times are estimates and may vary by city.',
    'returns', 'Unworn items with tags attached can be returned within 7 days of delivery.',
    'privacy', 'We only use your details to process orders and support requests.',
    'terms', 'Prices are listed in Pakistani rupees and include applicable taxes.'
  )
where id = 1;

